# test_parity_beta_binomial_family.jl — same-target parity vs drmTMB 0.7.0 for
# Beta, Binomial and BetaBinomial: fixed effects and a random intercept (1 | g).
#
# Fixed-effect Beta / Binomial reuse the committed `proportion-beta` and
# `binomial-trials` fixtures (expected.toml). The BetaBinomial fixed-effect and
# all three `(1 | g)` cells use the fixtures `beta-mu-ranef`, `binomial-mu-ranef`,
# `betabinomial-fixed` and `betabinomial-mu-ranef`, generated by
#
#   Rscript test/parity/gen_beta_binomial_family_parity.R
#
# (drmTMB 0.7.0; seeds 20261031-20261034). The R numbers below are generated
# outputs only; no drmTMB source is vendored.
#
# KNOWN MISMATCH (marked @test_broken): on the `(1 | g)` cells the coefficients
# and the RE SD agree to ~1e-3, but logLik differs from drmTMB by 0.06-0.19.
# drmTMB integrates the intercept with a TMB Laplace approximation; DRModels.jl
# uses adaptive Gauss-Hermite quadrature — two different approximations of the
# same integral, so logLik is not bit-comparable. The tight logLik check is
# therefore @test_broken, with a looser same-target check alongside it.

module TestParityBetaBinomialFamily

using DRModels
using Test
using DelimitedFiles: readdlm
using TOML

const FIX = joinpath(@__DIR__, "parity", "fixtures")

function _load(slug)
    raw, h = readdlm(joinpath(FIX, slug, "data.csv"), ','; header = true)
    cols = Symbol.(strip.(string.(vec(h))))
    vals = [c == :g ? string.(raw[:, i]) : Float64.(raw[:, i]) for (i, c) in enumerate(cols)]
    return NamedTuple{Tuple(cols)}(Tuple(vals))
end

@testset "Beta / Binomial / BetaBinomial parity vs drmTMB 0.7.0" begin

    @testset "Beta fixed (proportion-beta, committed fixture)" begin
        exp = TOML.parsefile(joinpath(FIX, "proportion-beta", "expected.toml"))
        d = _load("proportion-beta")
        fit = drm(bf(@formula(y ~ x), @formula(sigma ~ 1)), DRModels.Beta(); data = d)
        @test coef(fit, :mu)[1] ≈ exp["coef"]["mu_(Intercept)"] atol = 1e-3
        @test coef(fit, :mu)[2] ≈ exp["coef"]["mu_x"] atol = 1e-3
        @test coef(fit, :sigma)[1] ≈ exp["coef"]["sigma_(Intercept)"] atol = 1e-3
        @test loglik(fit) ≈ exp["fit"]["loglik"] atol = 1e-3
    end

    @testset "Binomial fixed (binomial-trials, committed fixture)" begin
        exp = TOML.parsefile(joinpath(FIX, "binomial-trials", "expected.toml"))
        d = _load("binomial-trials")
        fit = drm(bf(@formula(cbind(successes, failures) ~ x)), DRModels.Binomial(); data = d)
        @test coef(fit, :mu)[1] ≈ exp["coef"]["mu_(Intercept)"] atol = 1e-3
        @test coef(fit, :mu)[2] ≈ exp["coef"]["mu_x"] atol = 1e-3
        @test loglik(fit) ≈ exp["fit"]["loglik"] atol = 1e-3
    end

    @testset "BetaBinomial fixed" begin
        d = _load("betabinomial-fixed")
        fit = drm(bf(@formula(cbind(successes, failures) ~ x), @formula(sigma ~ 1)),
                  BetaBinomial(); data = d)
        @test coef(fit, :mu)[1] ≈ -0.1502325372 atol = 1e-3
        @test coef(fit, :mu)[2] ≈ 0.4940450415 atol = 1e-3
        @test coef(fit, :sigma)[1] ≈ -1.166742708 atol = 1e-3
        @test loglik(fit) ≈ -850.958527 atol = 1e-3
    end

    @testset "Beta (1 | g)" begin
        d = _load("beta-mu-ranef")
        fit = drm(bf(@formula(y ~ x + (1 | g)), @formula(sigma ~ 1)), DRModels.Beta(); data = d)
        @test fit.converged
        @test coef(fit, :mu)[1] ≈ -0.2000044334 atol = 2e-3
        @test coef(fit, :mu)[2] ≈ 0.504732273 atol = 2e-3
        @test coef(fit, :sigma)[1] ≈ -1.514802114 atol = 2e-3
        @test exp(coef(fit, :resd)[1]) ≈ 0.3748078683 rtol = 0.01
        @test loglik(fit) ≈ 242.9813254 atol = 0.3          # same-target
        @test_broken isapprox(loglik(fit), 242.9813254; atol = 1e-3)  # Laplace vs AGHQ
    end

    @testset "Binomial (1 | g)" begin
        d = _load("binomial-mu-ranef")
        fit = drm(bf(@formula(cbind(successes, failures) ~ x + (1 | g))),
                  DRModels.Binomial(); data = d)
        @test fit.converged
        @test coef(fit, :mu)[1] ≈ -0.1634994205 atol = 2e-3
        @test coef(fit, :mu)[2] ≈ 0.4896786127 atol = 2e-3
        @test exp(coef(fit, :resd)[1]) ≈ 0.7189950594 rtol = 0.01
        @test loglik(fit) ≈ -725.285481 atol = 0.3
        @test_broken isapprox(loglik(fit), -725.285481; atol = 1e-3)
    end

    @testset "BetaBinomial (1 | g)" begin
        d = _load("betabinomial-mu-ranef")
        fit = drm(bf(@formula(cbind(successes, failures) ~ x + (1 | g)), @formula(sigma ~ 1)),
                  BetaBinomial(); data = d)
        @test fit.converged
        @test coef(fit, :mu)[1] ≈ -0.1376231 atol = 2e-3
        @test coef(fit, :mu)[2] ≈ 0.3947334722 atol = 2e-3
        @test coef(fit, :sigma)[1] ≈ -1.219226746 atol = 2e-3
        @test exp(coef(fit, :resd)[1]) ≈ 0.4464803099 rtol = 0.01
        @test loglik(fit) ≈ -862.8539878 atol = 0.3
        @test_broken isapprox(loglik(fit), -862.8539878; atol = 1e-3)
    end
end

end # module
